@sync_client_id_binary binary(16),
@sync_client_id uniqueidentifier,
@sync_server_id_binary binary(16),
@sync_context_site_guid uniqueidentifier,
@sync_context_site_id nvarchar(30),
@sync_context_site_guid_list nvarchar(1024),
@sync_context_site_id_list nvarchar(1024),
@sync_table_name nvarchar(512),
@sync_batch_size_tblTransactionLineItems int,
@sync_bypass_insert_update_extraction bit,
@sync_request_type int,
@sync_first_time_sync_option_tblTransactionLineItems int
AS
BEGIN
    DECLARE @minValidVersion BigInt 
    DECLARE @sync_last_received_anchor_varbinary varbinary(8)
    DECLARE @sync_new_received_anchor_varbinary varbinary(8)

    SET @sync_last_received_anchor_varbinary = CONVERT(varbinary(8), @sync_last_received_anchor);
    SET @sync_new_received_anchor_varbinary = CONVERT(varbinary(8), @sync_new_received_anchor);

    -- The FuelsManager Client selection for inserts is not coded to support a default SELECT ALL in order to push into the Enterprise.  This is by design.
    IF ((@sync_request_type = 4)
        OR (@sync_bypass_insert_update_extraction IS NOT NULL AND @sync_bypass_insert_update_extraction = 1))
    BEGIN
        SELECT [dbo].[tblTransactionLineItems].[SequenceID],[dbo].[tblTransactionLineItems].[MeterStart],[dbo].[tblTransactionLineItems].[MeterStop],[dbo].[tblTransactionLineItems].[GrossQuantity],[dbo].[tblTransactionLineItems].[DeliveredGrossQuantity],[dbo].[tblTransactionLineItems].[Temperature],[dbo].[tblTransactionLineItems].[Vcf],[dbo].[tblTransactionLineItems].[Density],[dbo].[tblTransactionLineItems].[Product],[dbo].[tblTransactionLineItems].[ProductCode],[dbo].[tblTransactionLineItems].[ProductType],[dbo].[tblTransactionLineItems].[ProductPrice],[dbo].[tblTransactionLineItems].[CLIN],[dbo].[tblTransactionLineItems].[NetQuantity],[dbo].[tblTransactionLineItems].[DeliveredNetQuantity],[dbo].[tblTransactionLineItems].[Pressure],[dbo].[tblTransactionLineItems].[ContractNumber],[dbo].[tblTransactionLineItems].[DestinationRegistrationID],[dbo].[tblTransactionLineItems].[DestinationSerialNumber],[dbo].[tblTransactionLineItems].[DestinationEquipmentType],[dbo].[tblTransactionLineItems].[DestinationEquipmentModel],[dbo].[tblTransactionLineItems].[DestinationCompanyEquipmentID],[dbo].[tblTransactionLineItems].[DestinationCompartmentID],[dbo].[tblTransactionLineItems].[SourceRegistrationID],[dbo].[tblTransactionLineItems].[SourceSerialNumber],[dbo].[tblTransactionLineItems].[SourceEquipmentType],[dbo].[tblTransactionLineItems].[SourceEquipmentModel],[dbo].[tblTransactionLineItems].[SourceCompanyEquipmentID],[dbo].[tblTransactionLineItems].[SourceCompartmentID],[dbo].[tblTransactionLineItems].[MeterFactor],[dbo].[tblTransactionLineItems].[LineItemSequenceNumber],[dbo].[tblTransactionLineItems].[BatchNumber],[dbo].[tblTransactionLineItems].[DocumentNumber],[dbo].[tblTransactionLineItems].[LineFill],[dbo].[tblTransactionLineItems].[BottomVolume],[dbo].[tblTransactionLineItems].[NetCapacity],[dbo].[tblTransactionLineItems].[Customs],[dbo].[tblTransactionLineItems].[ArmNumber],[dbo].[tblTransactionLineItems].[LineNumber],[dbo].[tblTransactionLineItems].[OperatorID],[dbo].[tblTransactionLineItems].[TankStatus],[dbo].[tblTransactionLineItems].[MeterStartDateTime],[dbo].[tblTransactionLineItems].[MeterStopDateTime],[dbo].[tblTransactionLineItems].[Pit],[dbo].[tblTransactionLineItems].[RequestedDateTime],[dbo].[tblTransactionLineItems].[DispatchedDateTime],[dbo].[tblTransactionLineItems].[AcknowledgedDateTime],[dbo].[tblTransactionLineItems].[OnLocationTime],[dbo].[tblTransactionLineItems].[ValidationDateTime],[dbo].[tblTransactionLineItems].[CompletionDateTime],[dbo].[tblTransactionLineItems].[ReceiptVariance],[dbo].[tblTransactionLineItems].[DifferentialPressure],[dbo].[tblTransactionLineItems].[LoadRackVariance],[dbo].[tblTransactionLineItems].[RequestedBy],[dbo].[tblTransactionLineItems].[FreezePoint],[dbo].[tblTransactionLineItems].[DeleteFlag],[dbo].[tblTransactionLineItems].[StorageLocationID],[dbo].[tblTransactionLineItems].[MeterID],[dbo].[tblTransactionLineItems].[AdditiveProfileID],[dbo].[tblTransactionLineItems].[CreatedBy],[dbo].[tblTransactionLineItems].[CreatedDate],[dbo].[tblTransactionLineItems].[UpdatedBy],[dbo].[tblTransactionLineItems].[UpdatedDate],[dbo].[tblTransactionLineItems].[PresetAmount],[dbo].[tblTransactionLineItems].[EngineeringUnitsIndex],[dbo].[tblTransactionLineItems].[CustomerProductName],[dbo].[tblTransactionLineItems].[CustomerProductCode],CONVERT(CHAR(10), [dbo].[tblTransactionLineItems].[TransactionInventoryDate], 111) AS [TransactionInventoryDate],[dbo].[tblTransactionLineItems].[COAWaiver],[dbo].[tblTransactionLineItems].[COANote],[dbo].[tblTransactionLineItems].[COAID],[dbo].[tblTransactionLineItems].[Tax1],[dbo].[tblTransactionLineItems].[Tax2],[dbo].[tblTransactionLineItems].[Tax3],[dbo].[tblTransactionLineItems].[Tax4],[dbo].[tblTransactionLineItems].[Tax5],[dbo].[tblTransactionLineItems].[TransVersion],[dbo].[tblTransactionLineItems].[LoadingLocationID],[dbo].[tblTransactionLineItems].[ImproperAdditization],[dbo].[tblTransactionLineItems].[BrokenBlend],[dbo].[tblTransactionLineItems].[ContaminatePrompt],[dbo].[tblTransactionLineItems].[CompartmentsPreviouslyLoaded],[dbo].[tblTransactionLineItems].[CompartmentsEmpty],[dbo].[tblTransactionLineItems].[Flag01],[dbo].[tblTransactionLineItems].[Flag02],[dbo].[tblTransactionLineItems].[Flag03],[dbo].[tblTransactionLineItems].[Flag04],[dbo].[tblTransactionLineItems].[Flag05],[dbo].[tblTransactionLineItems].[Flag06],[dbo].[tblTransactionLineItems].[Number01],[dbo].[tblTransactionLineItems].[Number02],[dbo].[tblTransactionLineItems].[Number03],[dbo].[tblTransactionLineItems].[Number04],[dbo].[tblTransactionLineItems].[Number05],[dbo].[tblTransactionLineItems].[Number06],[dbo].[tblTransactionLineItems].[OdometerHours],[dbo].[tblTransactionLineItems].[EndDeliveryDate],[dbo].[tblTransactionLineItems].[RequestedDeliveryDate],[dbo].[tblTransactionLineItems].[InvoiceNumber],[dbo].[tblTransactionLineItems].[InvoiceLineNumber],[dbo].[tblTransactionLineItems].[AlternativeGrossVolume],[dbo].[tblTransactionLineItems].[AlternativeNetVolume],[dbo].[tblTransactionLineItems].[AlternativeUnits],[dbo].[tblTransactionLineItems].[TankLevel],[dbo].[tblTransactionLineItems].[TankLevelUnits],[dbo].[tblTransactionLineItems].[Date01],[dbo].[tblTransactionLineItems].[Date02],[dbo].[tblTransactionLineItems].[Date03],[dbo].[tblTransactionLineItems].[Date04],[dbo].[tblTransactionLineItems].[NonDomesticPrice],[dbo].[tblTransactionLineItems].[CurrencyUnit],[dbo].[tblTransactionLineItems].[ExchangeRate],[dbo].[tblTransactionLineItems].[QualityTestNumber],[dbo].[tblTransactionLineItems].[Odometer],[dbo].[tblTransactionLineItems].[DeliveryLocation],[dbo].[tblTransactionLineItems].[Variance],[dbo].[tblTransactionLineItems].[PartialFill],[dbo].[tblTransactionLineItems].[MassQuantity],[dbo].[tblTransactionLineItems].[NetManualValueFlag],[dbo].[tblTransactionLineItems].[MassManualValueFlag],[dbo].[tblTransactionLineItems].[GrossManualValueFlag],[dbo].[tblTransactionLineItems].[VcfManualValueFlag],[dbo].[tblTransactionLineItems].[DeliveredGrossManualValueFlag],[dbo].[tblTransactionLineItems].[DeliveredNetManualValueFlag],[dbo].[tblTransactionLineItems].[TransactionLineItemGuid],[dbo].[tblTransactionLineItems].[LookupTransactionStatusIndex],[dbo].[tblTransactionLineItems].[LookupQualityIndex],[dbo].[tblTransactionLineItems].[StorageLocationTankGuid],[dbo].[tblTransactionLineItems].[AdditiveProfileGuid],[dbo].[tblTransactionLineItems].[DestinationCompartmentEquipmentGuid],[dbo].[tblTransactionLineItems].[DestinationEquipmentGuid],[dbo].[tblTransactionLineItems].[OperatorPersonnelGuid],[dbo].[tblTransactionLineItems].[ProductGuid],[dbo].[tblTransactionLineItems].[SourceCompartmentEquipmentGuid],[dbo].[tblTransactionLineItems].[SourceEquipmentGuid],[dbo].[tblTransactionLineItems].[TransactionGuid],[dbo].[tblTransactionLineItems].[CurrencyGuid],[dbo].[tblTransactionLineItems].[OrderReferenceTransactionLineItemGuid],[dbo].[tblTransactionLineItems].[LoadingLocationStationGuid],[dbo].[tblTransactionLineItems].[MeterGuid],[dbo].[tblTransactionLineItems].[PackageManualValueFlag],[dbo].[tblTransactionLineItems].[CleanLineItem],[dbo].[tblTransactionLineItems].[CleanLineDeductItem],[dbo].[tblTransactionLineItems].[CleanLineDeductQuantity],[dbo].[tblTransactionLineItems].[CleanLinePackQuantity],[dbo].[tblTransactionLineItems].[DualFuelingModeFlag],[dbo].[tblTransactionLineItems].[DualFuelingPrimaryFlag],[dbo].[tblTransactionLineItems].[EngineRunTime],[dbo].[tblTransactionLineItems].[FlowRate],[dbo].[tblTransactionLineItems].[FuelCompressionFactor],[dbo].[tblTransactionLineItems].[HydrantPressure],[dbo].[tblTransactionLineItems].[MobileDeviceID],[dbo].[tblTransactionLineItems].[MobileDeviceGuid],[dbo].[tblTransactionLineItems].[TemperatureQualityStatus],[dbo].[tblTransactionLineItems].[MeterStartObtainedAutomaticallyFlag],[dbo].[tblTransactionLineItems].[MeterStopObtainedAutomaticallyFlag],[dbo].[tblTransactionLineItems].[NetVolumeIndicator], [dbo].[tblTransactionLineItems].[_RowVersion]
            FROM [dbo].[tblTransactionLineItems]
            WHERE 1=2;
            
        RETURN;
    END

    IF (@sync_batch_size_tblTransactionLineItems IS NULL OR 
        (@sync_batch_size_tblTransactionLineItems IS NOT NULL AND @sync_batch_size_tblTransactionLineItems = 0))
    BEGIN
        SET @sync_batch_size_tblTransactionLineItems = 2147483647;
    END


        -- We only do this on tblTransactionLineItems so we know what which tblTransactionLineItems records are being processed.
        -- Synchronization will only synchronize other dependent records that are associated with the tblTransactionLineItems records
        -- that were included.

        -- Get a list of the Owned/Assigned Entities and locate any newly inserted entities
        -- and/or any new entity site assignments (if assignable).
        -- Tables that are associated with tblTransactionLineItems are filtered through a temp #SyncTable based on the selected tblTransactionLineItems records
        -- and therefore are not limited by a TOP(n) clause
        -- 
        SELECT [dbo].[tblTransactionLineItems].[SequenceID],[dbo].[tblTransactionLineItems].[MeterStart],[dbo].[tblTransactionLineItems].[MeterStop],[dbo].[tblTransactionLineItems].[GrossQuantity],[dbo].[tblTransactionLineItems].[DeliveredGrossQuantity],[dbo].[tblTransactionLineItems].[Temperature],[dbo].[tblTransactionLineItems].[Vcf],[dbo].[tblTransactionLineItems].[Density],[dbo].[tblTransactionLineItems].[Product],[dbo].[tblTransactionLineItems].[ProductCode],[dbo].[tblTransactionLineItems].[ProductType],[dbo].[tblTransactionLineItems].[ProductPrice],[dbo].[tblTransactionLineItems].[CLIN],[dbo].[tblTransactionLineItems].[NetQuantity],[dbo].[tblTransactionLineItems].[DeliveredNetQuantity],[dbo].[tblTransactionLineItems].[Pressure],[dbo].[tblTransactionLineItems].[ContractNumber],[dbo].[tblTransactionLineItems].[DestinationRegistrationID],[dbo].[tblTransactionLineItems].[DestinationSerialNumber],[dbo].[tblTransactionLineItems].[DestinationEquipmentType],[dbo].[tblTransactionLineItems].[DestinationEquipmentModel],[dbo].[tblTransactionLineItems].[DestinationCompanyEquipmentID],[dbo].[tblTransactionLineItems].[DestinationCompartmentID],[dbo].[tblTransactionLineItems].[SourceRegistrationID],[dbo].[tblTransactionLineItems].[SourceSerialNumber],[dbo].[tblTransactionLineItems].[SourceEquipmentType],[dbo].[tblTransactionLineItems].[SourceEquipmentModel],[dbo].[tblTransactionLineItems].[SourceCompanyEquipmentID],[dbo].[tblTransactionLineItems].[SourceCompartmentID],[dbo].[tblTransactionLineItems].[MeterFactor],[dbo].[tblTransactionLineItems].[LineItemSequenceNumber],[dbo].[tblTransactionLineItems].[BatchNumber],[dbo].[tblTransactionLineItems].[DocumentNumber],[dbo].[tblTransactionLineItems].[LineFill],[dbo].[tblTransactionLineItems].[BottomVolume],[dbo].[tblTransactionLineItems].[NetCapacity],[dbo].[tblTransactionLineItems].[Customs],[dbo].[tblTransactionLineItems].[ArmNumber],[dbo].[tblTransactionLineItems].[LineNumber],[dbo].[tblTransactionLineItems].[OperatorID],[dbo].[tblTransactionLineItems].[TankStatus],[dbo].[tblTransactionLineItems].[MeterStartDateTime],[dbo].[tblTransactionLineItems].[MeterStopDateTime],[dbo].[tblTransactionLineItems].[Pit],[dbo].[tblTransactionLineItems].[RequestedDateTime],[dbo].[tblTransactionLineItems].[DispatchedDateTime],[dbo].[tblTransactionLineItems].[AcknowledgedDateTime],[dbo].[tblTransactionLineItems].[OnLocationTime],[dbo].[tblTransactionLineItems].[ValidationDateTime],[dbo].[tblTransactionLineItems].[CompletionDateTime],[dbo].[tblTransactionLineItems].[ReceiptVariance],[dbo].[tblTransactionLineItems].[DifferentialPressure],[dbo].[tblTransactionLineItems].[LoadRackVariance],[dbo].[tblTransactionLineItems].[RequestedBy],[dbo].[tblTransactionLineItems].[FreezePoint],[dbo].[tblTransactionLineItems].[DeleteFlag],[dbo].[tblTransactionLineItems].[StorageLocationID],[dbo].[tblTransactionLineItems].[MeterID],[dbo].[tblTransactionLineItems].[AdditiveProfileID],[dbo].[tblTransactionLineItems].[CreatedBy],[dbo].[tblTransactionLineItems].[CreatedDate],[dbo].[tblTransactionLineItems].[UpdatedBy],[dbo].[tblTransactionLineItems].[UpdatedDate],[dbo].[tblTransactionLineItems].[PresetAmount],[dbo].[tblTransactionLineItems].[EngineeringUnitsIndex],[dbo].[tblTransactionLineItems].[CustomerProductName],[dbo].[tblTransactionLineItems].[CustomerProductCode],CONVERT(CHAR(10), [dbo].[tblTransactionLineItems].[TransactionInventoryDate], 111) AS [TransactionInventoryDate],[dbo].[tblTransactionLineItems].[COAWaiver],[dbo].[tblTransactionLineItems].[COANote],[dbo].[tblTransactionLineItems].[COAID],[dbo].[tblTransactionLineItems].[Tax1],[dbo].[tblTransactionLineItems].[Tax2],[dbo].[tblTransactionLineItems].[Tax3],[dbo].[tblTransactionLineItems].[Tax4],[dbo].[tblTransactionLineItems].[Tax5],[dbo].[tblTransactionLineItems].[TransVersion],[dbo].[tblTransactionLineItems].[LoadingLocationID],[dbo].[tblTransactionLineItems].[ImproperAdditization],[dbo].[tblTransactionLineItems].[BrokenBlend],[dbo].[tblTransactionLineItems].[ContaminatePrompt],[dbo].[tblTransactionLineItems].[CompartmentsPreviouslyLoaded],[dbo].[tblTransactionLineItems].[CompartmentsEmpty],[dbo].[tblTransactionLineItems].[Flag01],[dbo].[tblTransactionLineItems].[Flag02],[dbo].[tblTransactionLineItems].[Flag03],[dbo].[tblTransactionLineItems].[Flag04],[dbo].[tblTransactionLineItems].[Flag05],[dbo].[tblTransactionLineItems].[Flag06],[dbo].[tblTransactionLineItems].[Number01],[dbo].[tblTransactionLineItems].[Number02],[dbo].[tblTransactionLineItems].[Number03],[dbo].[tblTransactionLineItems].[Number04],[dbo].[tblTransactionLineItems].[Number05],[dbo].[tblTransactionLineItems].[Number06],[dbo].[tblTransactionLineItems].[OdometerHours],[dbo].[tblTransactionLineItems].[EndDeliveryDate],[dbo].[tblTransactionLineItems].[RequestedDeliveryDate],[dbo].[tblTransactionLineItems].[InvoiceNumber],[dbo].[tblTransactionLineItems].[InvoiceLineNumber],[dbo].[tblTransactionLineItems].[AlternativeGrossVolume],[dbo].[tblTransactionLineItems].[AlternativeNetVolume],[dbo].[tblTransactionLineItems].[AlternativeUnits],[dbo].[tblTransactionLineItems].[TankLevel],[dbo].[tblTransactionLineItems].[TankLevelUnits],[dbo].[tblTransactionLineItems].[Date01],[dbo].[tblTransactionLineItems].[Date02],[dbo].[tblTransactionLineItems].[Date03],[dbo].[tblTransactionLineItems].[Date04],[dbo].[tblTransactionLineItems].[NonDomesticPrice],[dbo].[tblTransactionLineItems].[CurrencyUnit],[dbo].[tblTransactionLineItems].[ExchangeRate],[dbo].[tblTransactionLineItems].[QualityTestNumber],[dbo].[tblTransactionLineItems].[Odometer],[dbo].[tblTransactionLineItems].[DeliveryLocation],[dbo].[tblTransactionLineItems].[Variance],[dbo].[tblTransactionLineItems].[PartialFill],[dbo].[tblTransactionLineItems].[MassQuantity],[dbo].[tblTransactionLineItems].[NetManualValueFlag],[dbo].[tblTransactionLineItems].[MassManualValueFlag],[dbo].[tblTransactionLineItems].[GrossManualValueFlag],[dbo].[tblTransactionLineItems].[VcfManualValueFlag],[dbo].[tblTransactionLineItems].[DeliveredGrossManualValueFlag],[dbo].[tblTransactionLineItems].[DeliveredNetManualValueFlag],[dbo].[tblTransactionLineItems].[TransactionLineItemGuid],[dbo].[tblTransactionLineItems].[LookupTransactionStatusIndex],[dbo].[tblTransactionLineItems].[LookupQualityIndex],[dbo].[tblTransactionLineItems].[StorageLocationTankGuid],[dbo].[tblTransactionLineItems].[AdditiveProfileGuid],[dbo].[tblTransactionLineItems].[DestinationCompartmentEquipmentGuid],[dbo].[tblTransactionLineItems].[DestinationEquipmentGuid],[dbo].[tblTransactionLineItems].[OperatorPersonnelGuid],[dbo].[tblTransactionLineItems].[ProductGuid],[dbo].[tblTransactionLineItems].[SourceCompartmentEquipmentGuid],[dbo].[tblTransactionLineItems].[SourceEquipmentGuid],[dbo].[tblTransactionLineItems].[TransactionGuid],[dbo].[tblTransactionLineItems].[CurrencyGuid],[dbo].[tblTransactionLineItems].[OrderReferenceTransactionLineItemGuid],[dbo].[tblTransactionLineItems].[LoadingLocationStationGuid],[dbo].[tblTransactionLineItems].[MeterGuid],[dbo].[tblTransactionLineItems].[PackageManualValueFlag],[dbo].[tblTransactionLineItems].[CleanLineItem],[dbo].[tblTransactionLineItems].[CleanLineDeductItem],[dbo].[tblTransactionLineItems].[CleanLineDeductQuantity],[dbo].[tblTransactionLineItems].[CleanLinePackQuantity],[dbo].[tblTransactionLineItems].[DualFuelingModeFlag],[dbo].[tblTransactionLineItems].[DualFuelingPrimaryFlag],[dbo].[tblTransactionLineItems].[EngineRunTime],[dbo].[tblTransactionLineItems].[FlowRate],[dbo].[tblTransactionLineItems].[FuelCompressionFactor],[dbo].[tblTransactionLineItems].[HydrantPressure],[dbo].[tblTransactionLineItems].[MobileDeviceID],[dbo].[tblTransactionLineItems].[MobileDeviceGuid],[dbo].[tblTransactionLineItems].[TemperatureQualityStatus],[dbo].[tblTransactionLineItems].[MeterStartObtainedAutomaticallyFlag],[dbo].[tblTransactionLineItems].[MeterStopObtainedAutomaticallyFlag],[dbo].[tblTransactionLineItems].[NetVolumeIndicator],CT.InsertedRowVersion AS '_RowVersion'
            FROM [dbo].[tblTransactionLineItems]
                INNER JOIN #SyncTable ON #SyncTable.PK = [dbo].[tblTransactionLineItems].[TransactionGuid] 
                INNER JOIN [track].[tblTransactionLineItems] CT
                    ON CT.PK_TransactionLineItemGuid = [dbo].[tblTransactionLineItems].[TransactionLineItemGuid] 
            WHERE (#SyncTable.ChangeType = 'I' OR #SyncTable.ChangeType = 'U')
                AND (CT.DeletedRowVersion IS NULL)
                AND ((CT.InsertedRowVersion > @sync_last_received_anchor_varbinary)
                    AND (CT.InsertedRowVersion <= @sync_new_received_anchor_varbinary)
                    AND (CT.InsertedContext IS NULL OR CT.InsertedContext <> @sync_server_id_binary))   -- USE THE SERVER ID HERE SO WE DO NOT RETURN WHAT WAS JUST RECEIVED
        ORDER BY _RowVersion ASC

    SET @minValidVersion = 0;   -- This is used to detect Change Tracking cleanup
                                -- If we support this, we should add a column to SynchronizationTable
                                -- that records the MinValidVersion after change tracking information for
                                -- a table gets cleaned up.  I don't think this will be necessary.
    
    IF @minValidVersion > @sync_last_received_anchor 
        RAISERROR(N'(SII)Time between synchronization has exceeded the maximum amount of time for table ''%s'' (MIN: %I64d, LAST: %I64d).  To avoid data corruption and old data, the client must reinitialize its local database with a current refresh from the server.', 16, 3, @sync_table_name, @minValidVersion, @sync_last_received_anchor) 
END
